/bin/bash -lc "date '+%s %T'; PYTHONDONTWRITEBYTECODE=1 python3 -c 'import re,json,sys; from pathlib import Path; sys.path.insert(0,\"scripts\"); import check_gate_enforcement as c; ids={g[\"id\"] for g in json.load(open(\"scripts/gate_enforcement.json\"))[\"gates\"]}; targets=set();
for f in [Path(\"Makefile\"),Path(\"contracts/verification/Makefile\"),Path(\"contracts/verity/Makefile\")]:
 targets.update(m.group(1) for m in map(lambda x:re.match(r\""'^([A-Za-z0-9_.-]+):",x),f.read_text().splitlines()) if m)
wfs={p.name:c.load_workflow(p) or {} for p in Path(".github/workflows").glob("*.yml")}; found={t:sorted(n for n,w in wfs.items() if c.invokes_target(w,t)[0]) for t in targets}; print("workflow-invoked Make targets absent manifest:"); [(print(t,v)) for t,v in sorted(found.items()) if v and t not in ids]'"'"

